xql_query:
// ============================================================
// Rule: THM_Masquerading Word Execution from Downloads
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Masquerading Word Execution from Downloads.
// Severity: SEV_050_CRITICAL
// Category: EVASION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1036 - Masquerading
// Technique: T1036.006 - Masquerading: Space after Filename
// Technique: T1036.008 - Masquerading: Masquerade File Type

// 1) Fonte de dados
dataset = xdr_data

// 2) Selecione somente os campos úteis para a análise/investigação
| fields
    _time,
    agent_hostname,
    actor_effective_username,
    actor_process_image_name,
    actor_process_command_line,
    action_process_image_name,
    action_process_image_command_line,
    action_process_file_info,
    action_process_image_path,
    event_type,
    event_sub_type,
    agent_os_type

// 3) Restrinja para eventos de processo no Windows (início do processo)
| filter
    event_type     = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START
    and agent_os_type  = ENUM.AGENT_OS_WINDOWS

// 4) Caminho do executável: somente itens iniciados a partir de C:\Users\<user>\Downloads
//    Obs.: usa regex case-insensitive para achar o diretório de Downloads do usuário
| filter lowercase(action_process_image_path) ~= "[a-z]:\\users\\[^\\]+\\downloads"

// 5) Extraia metadados do arquivo (campos de File Info/PE resources)
| alter
    original_name = action_process_file_info -> original_name,   // Nome original do binário (ex.: WINWORD.EXE)
    description   = action_process_file_info -> description,     // Descrição do arquivo (ex.: Microsoft Word)
    company       = action_process_file_info -> company,         // Vendor/empresa
    internal_name = action_process_file_info -> internal_name    // Nome interno do binário (ex.: winword)

// 6) Perfil “parece Word”: descrição menciona “microsoft word” OU
//    internal_name == "winword" OU original_name == "winword.exe"
//    E: o nome real do arquivo (image_name) é diferente do original_name → possível masquerading.
| filter
    (
      lowercase(description)   contains "microsoft word"
      or lowercase(internal_name) = "winword"
      or lowercase(original_name) = "winword.exe"
    )
    and lowercase(original_name) != lowercase(action_process_image_name)
